-- ===========================================================================
-- Seed 14 : quizzes for the Python course
--
-- One per level. The scratchpad on each quiz page opens on a Python starter,
-- because starter_for_course() reads the course slug - so a learner unsure of
-- an answer can run the snippet rather than argue with themselves about it.
--
-- Generated by scratchpad/gen/build_quizzes.py, which also checks that every
-- single_choice has exactly one correct option and every multiple_choice has
-- at least two. A quiz that cannot be passed is not obvious from the SQL.
-- ===========================================================================

INSERT INTO assessment.quizzes
  (id, course_id, lesson_id, title, description, pass_percent, time_limit_seconds,
   max_attempts, shuffle_questions, shuffle_options, show_answers, status)
VALUES
  ('f0000001-0000-4000-8000-000000000014',
   'c0000001-0000-4000-8000-000000000008', 'e0000001-0000-4000-8000-00000000005d',
   'Level 1 Check: Values, Flow and Functions',
   'Names and values, the flow of control, and how arguments are passed. Every one of these can be settled in the scratchpad below the questions.',
   60, 600, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-000000000015',
   'c0000001-0000-4000-8000-000000000008', 'e0000001-0000-4000-8000-00000000005e',
   'Level 2 Check: Collections and Text',
   'Lists against tuples, dicts and sets, and the string methods that return rather than change.',
   60, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-000000000016',
   'c0000001-0000-4000-8000-000000000008', 'e0000001-0000-4000-8000-00000000005f',
   'Level 3 Check: Iteration, Classes and Errors',
   'Comprehensions, what a for loop actually does, dunder methods, and handling failure.',
   70, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-000000000017',
   'c0000001-0000-4000-8000-000000000008', 'e0000001-0000-4000-8000-000000000060',
   'Expert Exam: Python',
   'Decorators and closures, laziness, and a type system that is deliberately not enforced.',
   70, 1500, 3, 1, 1, 1, 'published')
ON DUPLICATE KEY UPDATE
  title = VALUES(title), description = VALUES(description),
  pass_percent = VALUES(pass_percent), status = VALUES(status);

INSERT INTO assessment.questions
  (id, quiz_id, kind, prompt, explanation, points, `position`, correct_text)
VALUES
  -- Level 1 Check: Values, Flow and Functions
  ('a1000001-0000-4000-8000-000000000201', 'f0000001-0000-4000-8000-000000000014', 'single_choice',
   'a = [1, 2, 3] then b = a, and b.append(4). What is a?',
   '[1, 2, 3, 4]. Assignment binds another name to the same list; it does not copy. a.copy(), list(a) or a[:] is how you ask for a copy.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-000000000202', 'f0000001-0000-4000-8000-000000000014', 'single_choice',
   'What does 0.1 + 0.2 == 0.3 evaluate to, and why?',
   'False. A float is a binary approximation and 0.1 has no exact binary form, so the sum lands just past 0.3. Compare with math.isclose, or use Decimal when the decimal digits are the point - as they are for money.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-000000000203', 'f0000001-0000-4000-8000-000000000014', 'multiple_choice',
   'Which of these values are falsy in Python? Select all that apply.',
   'The empty list, the empty string, 0 and None are all falsy - as are 0.0, the empty dict and the empty tuple. The string "0" is not: it is a string with a character in it, which is why input() needs int() before you can trust a comparison.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-000000000204', 'f0000001-0000-4000-8000-000000000014', 'true_false',
   'def add(item, basket=[]) gives every call its own empty list.',
   'It does not. The default is evaluated once, when the function is defined, so every call that relies on it shares one list. The fix is basket=None and building the list inside the function.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-000000000205', 'f0000001-0000-4000-8000-000000000014', 'short_text',
   'Which built-in gives you the index and the item together as you loop over a sequence? Give just its name, in lower case.',
   'enumerate. It also takes a start= argument, so counting from 1 does not need arithmetic at the call site.',
   2, 5, 'enumerate'),

  -- Level 2 Check: Collections and Text
  ('a1000001-0000-4000-8000-000000000211', 'f0000001-0000-4000-8000-000000000015', 'single_choice',
   'scores = [3, 1, 2]. What does print(scores.sort()) show?',
   'None. sort() rearranges the list in place and returns nothing. sorted(scores) is the one that returns a new sorted list - assigning the result of sort() throws the list away.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-000000000212', 'f0000001-0000-4000-8000-000000000015', 'single_choice',
   'What is letters[::-1] for letters = list("abcd")?',
   '[''d'', ''c'', ''b'', ''a'']. A step of -1 walks the sequence backwards and produces a new list; the original is untouched.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-000000000213', 'f0000001-0000-4000-8000-000000000015', 'multiple_choice',
   'Which of these can be a dictionary key? Select all that apply.',
   'A key must be hashable, which in practice means immutable. Strings, integers and tuples of hashable things all qualify. A list does not - it can change, and a key that changes would be lost in the table it was filed under.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-000000000214', 'f0000001-0000-4000-8000-000000000015', 'single_choice',
   'What is the difference between "  a  b  ".split() and "  a  b  ".split(" ")?',
   'split() with no argument splits on any run of whitespace and drops the empty pieces, giving [''a'', ''b'']. split(" ") splits on each single space, so the runs and the leading and trailing spaces produce empty strings.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-000000000215', 'f0000001-0000-4000-8000-000000000015', 'true_false',
   'text.replace("a", "b") changes the string it is called on.',
   'It does not. Strings are immutable, so every string method returns a new string and leaves the original alone. The result has to be assigned somewhere or it is lost.',
   2, 5, NULL),

  -- Level 3 Check: Iteration, Classes and Errors
  ('a1000001-0000-4000-8000-000000000221', 'f0000001-0000-4000-8000-000000000016', 'single_choice',
   'squares = (x * x for x in range(5)). What does list(squares) give the second time you call it?',
   'An empty list. A generator is an iterator, and an iterator is consumed once - the first list() exhausted it. A list comprehension with square brackets would have built something re-readable instead.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-000000000222', 'f0000001-0000-4000-8000-000000000016', 'single_choice',
   'What must a class define for a for loop to work over it?',
   '__iter__, returning an iterator. The for loop knows nothing about lists: it asks the object for an iterator and calls __next__ until StopIteration. Implementing that protocol makes your type work everywhere a list does.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-000000000223', 'f0000001-0000-4000-8000-000000000016', 'multiple_choice',
   'Which statements about __repr__ and __str__ are true? Select all that apply.',
   '__repr__ is aimed at a developer and should ideally look like the code that would rebuild the object; __str__ is aimed at the end user. If only __repr__ is defined, str() falls back to it - which is why __repr__ is the one to write first.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-000000000224', 'f0000001-0000-4000-8000-000000000016', 'single_choice',
   'Why is a bare except: discouraged?',
   'It catches everything, including SystemExit and KeyboardInterrupt - so the program can no longer be stopped with Ctrl-C, and a bug that should have been loud disappears. Name the exceptions you actually expect.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-000000000225', 'f0000001-0000-4000-8000-000000000016', 'true_false',
   'A with block guarantees its cleanup runs even if the body raises.',
   'It does. __exit__ runs on the way out whatever the reason - a return, an exception or normal completion - which is the whole point of the protocol. Returning False from __exit__ lets the exception carry on afterwards.',
   2, 5, NULL),

  -- Expert Exam: Python
  ('a1000001-0000-4000-8000-000000000231', 'f0000001-0000-4000-8000-000000000017', 'single_choice',
   'What is @decorator above a function definition shorthand for?',
   'func = decorator(func). The decorator is called with the function and whatever it returns is bound to the name - which is why a decorator that forgets to return anything leaves you with None.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-000000000232', 'f0000001-0000-4000-8000-000000000017', 'single_choice',
   'What does functools.wraps do, and what breaks without it?',
   'It copies the wrapped function''s name, docstring and other metadata onto the wrapper. Without it every decorated function reports itself as wrapper, which breaks help(), debugging output and anything that inspects the signature.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-000000000233', 'f0000001-0000-4000-8000-000000000017', 'single_choice',
   'A function contains yield. What happens when you call it?',
   'Nothing runs. Calling it builds a generator object; the body executes only when something asks for a value, and pauses again at each yield. That is what lets a generator describe an endless sequence.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-000000000234', 'f0000001-0000-4000-8000-000000000017', 'multiple_choice',
   'Which statements about Python type hints are true? Select all that apply.',
   'Hints are annotations: nothing checks them at runtime, a checker like mypy checks them before it, and they are readable through __annotations__. They do not make anything faster - the interpreter does not use them to optimise.',
   3, 4, NULL),

  ('a1000001-0000-4000-8000-000000000235', 'f0000001-0000-4000-8000-000000000017', 'true_false',
   '[lambda x: x * i for i in range(3)] gives three functions that multiply by 0, 1 and 2.',
   'It does not. All three close over the same variable i, and by the time any of them is called the loop has finished and i is 2 - so all three multiply by 2. Binding it as a default, lambda x, i=i: x * i, captures the value of that round instead.',
   2, 5, NULL)
ON DUPLICATE KEY UPDATE
  prompt = VALUES(prompt), explanation = VALUES(explanation),
  points = VALUES(points), correct_text = VALUES(correct_text);

DELETE FROM assessment.question_options
 WHERE question_id IN (
   SELECT id FROM assessment.questions
    WHERE quiz_id IN ('f0000001-0000-4000-8000-000000000014',
                      'f0000001-0000-4000-8000-000000000015',
                      'f0000001-0000-4000-8000-000000000016',
                      'f0000001-0000-4000-8000-000000000017'));

INSERT INTO assessment.question_options (question_id, body, is_correct, `position`)
SELECT v.question_id, v.body, v.is_correct, v.pos
  FROM (
    SELECT 'a1000001-0000-4000-8000-000000000201' AS question_id, '[1, 2, 3, 4] - both names refer to one list' AS body, 1 AS is_correct, 1 AS pos
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000201', '[1, 2, 3] - b was a copy', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000201', '[1, 2, 3, 4, 4]', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000201', 'It raises, because a is immutable', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000202', 'False - floats are binary approximations', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000202', 'True - Python rounds the comparison', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000202', 'False - == never works on floats at all', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000202', 'It raises a precision error', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000203', '[]', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000203', '""', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000203', '0', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000203', '"0"', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000204', 'True', 0, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000204', 'False', 1, 2

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000211', 'None - sort() works in place', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000211', '[1, 2, 3]', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000211', '[3, 1, 2]', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000211', 'It raises a TypeError', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000212', 'A reversed copy of the list', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000212', 'The last element', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000212', 'The original list, reversed in place', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000212', 'An empty list', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000213', '"name"', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000213', '42', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000213', '(3, 4)', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000213', '[3, 4]', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000214', 'split() collapses runs of whitespace and drops empties; split(" ") does not', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000214', 'They are identical', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000214', 'split() only splits on the first space', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000214', 'split(" ") is faster but otherwise the same', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000215', 'True', 0, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000215', 'False', 1, 2

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000221', '[] - the generator was already consumed', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000221', '[0, 1, 4, 9, 16] again', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000221', 'It raises StopIteration', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000221', 'It restarts from the beginning', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000222', '__iter__, returning an iterator', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000222', '__len__ and __getitem__ only', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000222', '__list__', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000222', 'Nothing - any object can be iterated', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000223', '__repr__ is for developers, __str__ for end users', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000223', 'str() falls back to __repr__ when __str__ is missing', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000223', '__repr__ should ideally look like code that rebuilds the object', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000223', 'repr() falls back to __str__ when __repr__ is missing', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000224', 'It swallows KeyboardInterrupt and SystemExit along with real errors', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000224', 'It is slower than naming the exception', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000224', 'It is a syntax error in modern Python', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000224', 'It only catches the first exception raised', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000225', 'True', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000225', 'False', 0, 2

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000231', 'func = decorator(func)', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000231', 'decorator(func())', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000231', 'A type annotation the interpreter checks', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000231', 'A comment the interpreter ignores', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000232', 'It copies the original name, docstring and metadata onto the wrapper', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000232', 'It makes the decorator run faster', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000232', 'It stops the decorator being applied twice', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000232', 'It caches the wrapped function''s return value', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000233', 'It returns a generator without running any of the body', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000233', 'It runs the whole body and returns a list', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000233', 'It runs up to the first yield and returns that value', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000233', 'It raises unless it is called inside a for loop', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000234', 'They are not enforced when the program runs', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000234', 'A separate checker such as mypy is what enforces them', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000234', 'They are readable at runtime via __annotations__', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000234', 'They make the annotated code run faster', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000235', 'True', 0, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000235', 'False', 1, 2
  ) v;

CALL catalog.refresh_course_rollup('c0000001-0000-4000-8000-000000000008');
CALL `search`.reindex_all();
